WITH base AS (SELECT *, UPPER(account_type) AS account_type_upper FROM accounts WHERE opened_date >= TO_DATE('2023-05-17') AND customer_id IS NOT NULL) SELECT id, customer_id, account_type, balance, opened_date, account_type_upper, DENSE_RANK() OVER (PARTITION BY status ORDER BY balance DESC NULLS LAST) AS balance_dense_rank, ROW_NUMBER() OVER (PARTITION BY DATE_TRUNC('week', opened_date), status ORDER BY opened_date, id) AS seq_no FROM base
